// off_t lseek(int fd, off_t offset, int whence);

int file_fd;
off_t new_pos;

// Set position absolutely (1024 bytes from start)
new_pos = lseek(file_fd, 1024, SEEK_SET);

// Move relative to current position (512 bytes forward)
new_pos = lseek(file_fd, 512, SEEK_CUR);

// Move relative to end (-256 bytes from EOF)
new_pos = lseek(file_fd, -256, SEEK_END);

// Get current position without moving the pointer
off_t current = lseek(file_fd, 0, SEEK_CUR);

// Specialized seeks (Supported systems only)
off_t data_start = lseek(file_fd, 0, SEEK_DATA);
off_t hole_start = lseek(file_fd, 0, SEEK_HOLE);

// To seek backward, offset must be negative (except SEEK_SET)
new_pos = lseek(file_fd, -100, SEEK_CUR);
